// Package urip implements the URI (query-string escaped) format decoder and
// encoder.
//
// Behavior probed from the original yq v4.52.5 binary:
//   - Decode treats the ENTIRE input (including any trailing newline) as one
//     URL-query-escaped string, unescapes it (%XX and '+' -> space) and yields
//     exactly one document holding a single !!str scalar. Empty input yields
//     an empty string document.
//   - Invalid escapes (e.g. "%zz", "%", "%2") fail with Go's url error text,
//     e.g. `invalid URL escape "%zz"`.
//   - Encode only accepts !!str scalars; any other node fails with:
//     `cannot encode !!map as URI, can only operate on strings. Please first
//     pipe through another encoding operator to convert the value to a string`
//     (with the node's actual tag). Nodes are written back to back with no
//     separator and no trailing newline; nodes already written are kept when
//     a later node errors. -0/--nul-output appends a NUL byte after each node.
package urip

import (
	"fmt"
	"io"
	"net/url"

	"yq/node"
	"yq/settings"
)

// Decode parses URL-query-escaped input into a single document node holding
// one !!str scalar with the unescaped text.
func Decode(data []byte, s *settings.Settings) ([]*node.Node, error) {
	unescaped, err := url.QueryUnescape(string(data))
	if err != nil {
		return nil, err
	}
	return []*node.Node{node.NewDocument(node.NewString(unescaped))}, nil
}

// Encode writes each result node URL-query-escaped (space -> '+'). Only
// !!str scalars are supported.
func Encode(w io.Writer, nodes []*node.Node, s *settings.Settings) error {
	terminator := byte(0)
	if !s.NulOutput {
		terminator = 0 // write nothing after each node
	}
	for _, n := range nodes {
		if n == nil {
			continue
		}
		if n.Kind == node.DocumentKind {
			n = n.Root()
			if n == nil {
				continue
			}
		}
		if n.Kind != node.ScalarKind || n.Tag != "!!str" {
			return fmt.Errorf("cannot encode %s as URI, can only operate on strings. "+
				"Please first pipe through another encoding operator to convert the value to a string",
				tagOf(n))
		}
		if _, err := io.WriteString(w, url.QueryEscape(n.Value)); err != nil {
			return err
		}
		if s.NulOutput {
			if _, err := w.Write([]byte{terminator}); err != nil {
				return err
			}
		}
	}
	return nil
}

// tagOf returns the node's tag, deriving a sensible YAML tag from the kind
// when the tag is unset (defensive; real inputs always carry a tag).
func tagOf(n *node.Node) string {
	if n.Tag != "" {
		return n.Tag
	}
	switch n.Kind {
	case node.MappingKind:
		return "!!map"
	case node.SequenceKind:
		return "!!seq"
	case node.AliasKind:
		return "!!alias"
	case node.ScalarKind:
		return "!!str"
	}
	return "!!null"
}

