package urip

import (
	"bytes"
	"strings"
	"testing"

	"yq/node"
	"yq/settings"
)

// decodeOne decodes and returns the single root scalar node.
func decodeOne(t *testing.T, input string) *node.Node {
	t.Helper()
	docs, err := Decode([]byte(input), settings.New())
	if err != nil {
		t.Fatalf("Decode(%q) error: %v", input, err)
	}
	if len(docs) != 1 {
		t.Fatalf("Decode(%q) returned %d docs, want 1", input, len(docs))
	}
	root := docs[0].Root()
	if root == nil || root.Kind != node.ScalarKind || root.Tag != "!!str" {
		t.Fatalf("Decode(%q) root = %+v, want !!str scalar", input, root)
	}
	return root
}

func encode(t *testing.T, s *settings.Settings, nodes ...*node.Node) (string, error) {
	t.Helper()
	var buf bytes.Buffer
	err := Encode(&buf, nodes, s)
	return buf.String(), err
}

// --- Decode (probed from original binary) ---

func TestDecodeWholeInputIsOneString(t *testing.T) {
	// printf 'a=1&b=two+words&c[]=x' | yq -p uri
	// -> a=1&b=two words&c[]=x   (a single !!str scalar, NOT a map)
	n := decodeOne(t, "a=1&b=two+words&c[]=x")
	if n.Value != "a=1&b=two words&c[]=x" {
		t.Errorf("value = %q", n.Value)
	}
}

func TestDecodeKeepsTrailingNewline(t *testing.T) {
	// printf 'a+b\n' | yq -p uri  -> value "a b\n"
	n := decodeOne(t, "a+b\n")
	if n.Value != "a b\n" {
		t.Errorf("value = %q", n.Value)
	}
}

func TestDecodePercentAndPlus(t *testing.T) {
	// printf 'a+b%%2Bc' | yq -p uri  -> a b+c
	n := decodeOne(t, "a+b%2Bc")
	if n.Value != "a b+c" {
		t.Errorf("value = %q", n.Value)
	}
}

func TestDecodeEmptyInput(t *testing.T) {
	// printf '' | yq -p uri -o json  -> ""
	n := decodeOne(t, "")
	if n.Value != "" {
		t.Errorf("value = %q", n.Value)
	}
}

func TestDecodeLowercaseHexAndUtf8(t *testing.T) {
	// printf '%%c3%%a9' | yq -p uri  -> é
	n := decodeOne(t, "%c3%a9")
	if n.Value != "é" {
		t.Errorf("value = %q", n.Value)
	}
}

func TestDecodeEscapedSlash(t *testing.T) {
	// printf 'a%%2fb' | yq -p uri -o json  -> "a/b"
	n := decodeOne(t, "a%2fb")
	if n.Value != "a/b" {
		t.Errorf("value = %q", n.Value)
	}
}

func TestDecodeInvalidEscapes(t *testing.T) {
	// printf '%%zz' | yq -p uri  -> Error: bad file '-': invalid URL escape "%zz" (exit 1)
	cases := map[string]string{
		"%zz": `invalid URL escape "%zz"`,
		"%":   `invalid URL escape "%"`,
		"%2":  `invalid URL escape "%2"`,
	}
	for input, want := range cases {
		_, err := Decode([]byte(input), settings.New())
		if err == nil || err.Error() != want {
			t.Errorf("Decode(%q) err = %v, want %q", input, err, want)
		}
	}
}

// --- Encode (probed from original binary) ---

func TestEncodeBasic(t *testing.T) {
	// printf 'a+b%%2Bc' | yq -p uri -o uri  -> a+b%2Bc  (no trailing newline)
	got, err := encode(t, settings.New(), node.NewString("a b+c"))
	if err != nil {
		t.Fatal(err)
	}
	if got != "a+b%2Bc" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeSpecialChars(t *testing.T) {
	// yq -o uri on the YAML string
	// "a/b?c=d&e f+g%h#i:;'j,k~l_m.n-o!p(q)*r"
	in := "a/b?c=d&e f+g%h#i:;'j,k~l_m.n-o!p(q)*r"
	want := "a%2Fb%3Fc%3Dd%26e+f%2Bg%25h%23i%3A%3B%27j%2Ck~l_m.n-o%21p%28q%29%2Ar"
	got, err := encode(t, settings.New(), node.NewString(in))
	if err != nil {
		t.Fatal(err)
	}
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestEncodeNonAscii(t *testing.T) {
	// yq -n '"héllo😀"' -o uri  -> h%C3%A9llo%F0%9F%98%80
	got, err := encode(t, settings.New(), node.NewString("héllo😀"))
	if err != nil {
		t.Fatal(err)
	}
	if got != "h%C3%A9llo%F0%9F%98%80" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeControlChars(t *testing.T) {
	// yq -n '"line1\nline2"' -o uri -> line1%0Aline2 ; tab -> %09
	got, err := encode(t, settings.New(),
		node.NewString("line1\nline2"), node.NewString("tab\ttab"))
	if err != nil {
		t.Fatal(err)
	}
	if got != "line1%0Aline2tab%09tab" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeRejectsNonStrings(t *testing.T) {
	// yq -o uri on 3.14 / true / null / [1,2] / {"a":"b"} all fail with:
	// cannot encode !!X as URI, can only operate on strings. Please first
	// pipe through another encoding operator to convert the value to a string
	const suffix = " as URI, can only operate on strings. " +
		"Please first pipe through another encoding operator to convert the value to a string"
	cases := map[string]*node.Node{
		"!!int":   node.NewScalar("!!int", "123"),
		"!!float": node.NewScalar("!!float", "3.14"),
		"!!bool":  node.NewScalar("!!bool", "true"),
		"!!null":  node.NewNull(),
		"!!map":   node.NewMapping(),
		"!!seq":   node.NewSequence(),
	}
	for tag, n := range cases {
		out, err := encode(t, settings.New(), n)
		want := "cannot encode " + tag + suffix
		if err == nil || err.Error() != want {
			t.Errorf("tag %s: err = %v, want %q", tag, err, want)
		}
		if out != "" {
			t.Errorf("tag %s: wrote %q before failing", tag, out)
		}
	}
}

func TestEncodeMultipleNodesConcatenated(t *testing.T) {
	// printf '"one"\n--- "two"\n' | yq -o uri  -> onetwo (no separator/newline)
	got, err := encode(t, settings.New(), node.NewString("one"), node.NewString("two"))
	if err != nil {
		t.Fatal(err)
	}
	if got != "onetwo" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeWritesEarlierNodesBeforeError(t *testing.T) {
	// printf '"one"\n--- 3\n' | yq -o uri  -> writes "one", then errors (exit 1)
	got, err := encode(t, settings.New(), node.NewString("one"), node.NewScalar("!!int", "3"))
	if err == nil {
		t.Fatal("expected error")
	}
	if got != "one" {
		t.Errorf("got %q, want %q", got, "one")
	}
}

func TestEncodeNulOutput(t *testing.T) {
	// echo '"x y"' | yq -o uri -0  -> x+y\0
	s := settings.New()
	s.NulOutput = true
	got, err := encode(t, s, node.NewString("x y"), node.NewString("two"))
	if err != nil {
		t.Fatal(err)
	}
	if got != "x+y\x00two\x00" {
		t.Errorf("got %q", got)
	}
}

func TestEncodeEmptyString(t *testing.T) {
	// yq -n '""' -o uri  -> (empty output)
	got, err := encode(t, settings.New(), node.NewString(""))
	if err != nil {
		t.Fatal(err)
	}
	if got != "" {
		t.Errorf("got %q", got)
	}
}

func TestRoundTrip(t *testing.T) {
	inputs := []string{
		"a=1&b=two words&c[]=x",
		"héllo😀",
		"line1\nline2\n",
		"100% sure + certain",
		"",
	}
	for _, in := range inputs {
		var buf bytes.Buffer
		if err := Encode(&buf, []*node.Node{node.NewString(in)}, settings.New()); err != nil {
			t.Fatalf("Encode(%q): %v", in, err)
		}
		n := decodeOne(t, buf.String())
		if n.Value != in {
			t.Errorf("round trip of %q gave %q", in, n.Value)
		}
	}
}

func TestEncodeAcceptsDocumentWrappedString(t *testing.T) {
	// Defensive: contract says nodes are unwrapped, but tolerate documents.
	got, err := encode(t, settings.New(), node.NewDocument(node.NewString("a b")))
	if err != nil {
		t.Fatal(err)
	}
	if got != "a+b" {
		t.Errorf("got %q", got)
	}
}

func TestErrorMessageFormat(t *testing.T) {
	_, err := encode(t, settings.New(), node.NewMapping())
	if err == nil || !strings.HasPrefix(err.Error(), "cannot encode !!map as URI") {
		t.Errorf("err = %v", err)
	}
}
